        data: {"result": {"minY": 2.0, "minX": 0.0, "maxY": 330781.0, "series": [{"data": [[0.0, 110210.0], [100.0, 204.0], [200.0, 12.0]], "isOverall": false, "label": "DELETE - Delete Character", "isController": false}, {"data": [[0.0, 110297.0], [100.0, 190.0], [400.0, 2.0], [200.0, 9.0]], "isOverall": false, "label": "POST - Create Character", "isController": false}, {"data": [[0.0, 330781.0], [100.0, 586.0], [200.0, 27.0]], "isOverall": false, "label": "HTTP Request", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 400.0, "title": "Response Time Distribution"}},
